from google.cloud import speech

def get_speech_client():
    return speech.SpeechClient()

from google.cloud import speech
from speech_client import get_speech_client
from speech_models import TranscriptionResult

def poll_transcription(job_id):
    client = get_speech_client()
    operation = client.get_operation(name=job_id)

    if operation.done:
        response = operation.result()
        transcript = " ".join([result.alternatives[0].transcript for result in response.results])
        return TranscriptionResult(transcript=transcript)
    else:
        return {"status": "IN_PROGRESS"}

from google.cloud import translate_v3 as translate

def translate_transcript(text_segments, target_language_code, project_id):
    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    translations = []
    for text in text_segments:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "target_language_code": target_language_code,
            }
        )
        for translation in response.translations:
            translations.append(translation.translated_text)
    return translations

import googleapiclient.discovery

def moderate_transcript(text_segment):
    # Using the Perspective API for text moderation
    # https://developers.perspectiveapi.com/s/about-the-api
    client = googleapiclient.discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey="YOUR_API_KEY" # Replace with your actual API key
    )

    analyze_request = {
        'comment': {'text': text_segment},
        'requestedAttributes': {'TOXICITY': {}}
    }

    response = client.comments().analyze(body=analyze_request).execute()

    # A score of 0.5 or higher generally indicates a high likelihood of toxicity.
    toxicity_score = response['attributeScores']['TOXICITY']['summaryScore']['value']

    return {
        "text": text_segment,
        "toxicity_score": toxicity_score,
        "is_toxic": toxicity_score > 0.5 # Example threshold
    }
